const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/budget_views/%7Bbudget_view_id%7D/summary_rows',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    filters: 'SOME_ARRAY_VALUE',
    group_by: ['[object Object]', '[object Object]'],
    comparison: 'SOME_OBJECT_VALUE',
    column_ids: 'SOME_ARRAY_VALUE',
    source_snapshot_id: 'SOME_STRING_VALUE',
    filter_groups: 'SOME_ARRAY_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/budget_views/%7Bbudget_view_id%7D/summary_rows?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters=SOME_ARRAY_VALUE&group_by=%5Bobject%20Object%5D&group_by=%5Bobject%20Object%5D&comparison=SOME_OBJECT_VALUE&column_ids=SOME_ARRAY_VALUE&source_snapshot_id=SOME_STRING_VALUE&filter_groups=SOME_ARRAY_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
